import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"8、【比】 坤下坎上","description":"周易口訣義 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"周易口訣義 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"classics/koujueyi/010.md","filePath":"classics/koujueyi/010.md"}'),r={name:"classics/koujueyi/010.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><p>彖曰：比，吉也。比，輔也，下順從也。「原筮元永貞無咎」，以剛中也。「不寧方來」，上下應也。「後夫兇」，其道窮也。象曰：地上有水，「比」。先王以建萬國，親諸侯。</p><p>初六：有孚比之，無咎。有孚盈缶，終來有他，吉。</p><p>象曰：比之初六，「有他吉」也。</p><p>六二：比之自內，貞吉。</p><p>象曰：「比之自內」，不自失也。</p><p>六三：比之匪人。</p><p>象曰：「比之匪人」，不亦傷乎！</p><p>六四：外比之，貞吉。</p><p>象曰：「外比」於賢，以從上也。</p><p>九五：顯比，王用三驅，失前禽。邑人不誡，吉。</p><p>象曰：「顯比」之吉，位正中也。舍逆取順，「失前禽」也。「邑人不誡」，上使中也。</p><p>上六：比之無首，兇。</p><p>象曰：「比之無首」，無所終也。</p><p>解讀</p><p>「比吉，原筮元永貞無咎」者，「比」是親比之義，與人親比，自然獲吉，故曰「比吉」也。與人親比，必須尋其根源。筮是問也，審其情原，方得「大永貞」，是貞正之人與之親比，乃得「無咎」。若遇奸邪之人，則不能保其親比之道。「不寧方來」者，「比」是寧樂之時，亦猶人君有德，不寧之方，悉來歸化焉。「後夫兇」者，「比」道宜速，若處後而來，被人疏隔，所以「兇」也。</p><p>象曰：「地上有水，比，先王以建萬國，親諸侯」者，子夏傳雲「地得水而柔，水得地而流」是也。「先王以建萬國，親諸侯」者，萬方各據境域，謂王者封建有功之臣也。「親諸侯」，謂爵賞及親友，令助君之化也。</p><p>初六，有孚比之，無咎。有孚盈缶，終來有他，吉者，處比之初，唯須以信待物，先須以信，始得免咎，故曰「有孚比之，無咎」。初六既無偏應，來者皆與相親，著信立誠，盈溢於質素之器，心無偏黨，應者非一，故有他人而來，終亦不相拒，故有他吉。</p><p>「六二，比之自內，貞吉」者，專應於五，不能更比他人，劣於初六，故得當家內正之吉也。</p><p>「六三，比之匪人」者，匪，非也。處比之時，雖近二四，情不相得，二四柔謟，非己所親，故曰「匪人」，謂非己親比之人也。</p><p>「六四：外比之，貞吉」者，本應在初，初既遠，即親於所近，九五有德行，可以親比之，故稱「貞吉」也。</p><p>「九五：顯比，王用三驅，失前禽，邑人不誡，吉」者，處比之時，居得尊位，固當心無偏黨，來者比親，而乃獨應於二，顯明親比之道，是用心𥚹拘，故曰「顯比」也。夫不能普及於物，而乃親於二，亦如王用三驅，田獵相似。凡三驅之禮，受來惡去，故逆來趣己者舍之，背已而走者射之，故「失前禽」也。然有中正之德，不妄加之徵伐，所有背叛，必須攻討，以其當邑之人，不須防誡而得吉矣。獨親邑人，心不弘通，非君上之道可以為君上之使，故云「上使中」也。</p><p>「上六：比之無首，兇」者，處比之終，最在於外，眾皆先至而相親比，己獨在後，違眾叛義，所以「兇」也。若禹會諸侯於塗山，防風氏後至，禹乃戮之，此之謂也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
